IMessage message = new PrefixMessage(new PlainMessage());
Console.WriteLine(message.Read());

interface IMessage { string Read(); }
class PlainMessage : IMessage
{
    public string Read() => "Xin chào";
}
class PrefixMessage(IMessage inner) : IMessage
{
    public string Read() => "[Thông báo] " + inner.Read();
}
